mapper.sql:
WHERE c.DELETE_YN =

    1
    0




    AND c.PROGRESS_STATUS = #{progressStatus}




    AND c.POST_STATUS = #{postStatus}




    AND (
        LOCATE(#{keyword}, c.TITLE) > 0
        OR LOCATE(#{keyword}, c.CONTENT) > 0
    )




    AND c.END_DATE > #{fromDate}



    AND c.START_DATE < DATE_ADD(#{toDate}, INTERVAL 1 DAY)

mapper.select:
SELECT
    EXISTS (
        SELECT 1
        FROM CHALLENGE_ENTRY ce
        WHERE ce.CHAL_CODE = #{code}
    )
    OR
    EXISTS (
        SELECT 1
        FROM FEED f
        WHERE f.CHAL_CODE = #{code}
    )

mapper.update:
UPDATE CHALLENGE
SET
    DELETE_YN = 1,
    UPDATED_BY = #{adminId},
    UPDATED_AT = #{updatedAt}

WHERE CODE = #{code}
  AND DELETE_YN = 0

  AND NOT EXISTS (
      SELECT 1
      FROM CHALLENGE_ENTRY ce
      WHERE ce.CHAL_CODE = #{code}
  )

  AND NOT EXISTS (
      SELECT 1
      FROM FEED f
      WHERE f.CHAL_CODE = #{code}
  )

UPDATE CHALLENGE
SET
    PROGRESS_STATUS = 'ENDED',
    END_DATE = #{endedAt},
    UPDATED_BY = #{adminId},
    UPDATED_AT = #{endedAt}

WHERE CODE = #{code}
  AND DELETE_YN = 0
  AND PROGRESS_STATUS IN ('WAITING', 'IN_PROGRESS')
  AND START_DATE <= #{endedAt}
  AND END_DATE > #{endedAt}
